def check(seq):
    if sorted(seq) != list(range(24)):
        return False
    diffs = [abs(seq[i] - seq[i+1]) for i in range(23)]
    if sorted(diffs) != list(range(1, 24)):
        return False
    return True

seq = [0, 23, 1, 22, 2, 21, 3, 20, 4, 19, 5, 18, 6, 17, 7, 16, 8, 15, 9, 14, 10, 13, 11, 12]
print(check(seq))
